/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_control">_control</param>
public void avaCreateCustQuotationJour(FormControl _control)
{
    Args args = new Args();
    args.record(this.SalesQuotationTable);
    args.caller(_control);

    new MenuFunction(menuItemActionStr(AVACreateQuotationJournal), MenuItemType::Action).run(args);
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_control">_control</param>
public void avaCreateEmail(FormControl _control)
{
    CustQuotationJour           lastCustQuotationJour = CustQuotationJour::avaFindLatestQuotation(this.SalesQuotationTable.QuotationId);
    Args args = new Args();
    args.record(lastCustQuotationJour);
    args.caller(_control);

    new MenuFunction(menuItemActionStr(AVAERQuotationEmailCreation), MenuItemType::Action).run(args);
}

/// <summary>
///     AVA <c>init</c> method.
/// </summary>
void init()
{
    Args                    locArgs;
    FormDataSource          locFormDataSource;
    HcmWorkerRecId          locHcmWorkerRecId;

    Query                   locQuery;
    QueryBuildDataSource    locQueryBuildDataSource;
    QueryBuildRange         locQueryBuildRangeResponsible;
    QueryBuildRange         locQueryBuildRangePosted;

    locArgs = this.args();

    next init();

    if(locArgs)
    {
        switch(locArgs.menuItemName())
        {
            case menuItemDisplayStr(SalesQuotationsListPage_MyQuotations):
                locHcmWorkerRecId               = HcmWorkerLookup::currentWorker();

                locFormDataSource               = this.SalesQuotationTable_DS;

                locQuery                        = locFormDataSource.query();
                locQueryBuildDataSource         = locFormDataSource.queryBuildDataSource();

                locQueryBuildRangeResponsible   = SysQuery::findOrCreateRange(locQuery.datasourceTable(tableNum(SalesQuotationTable)), fieldNum(SalesQuotationTable, WorkerSalesResponsible));
                locQueryBuildDataSource.clearRange(fieldNum(SalesQuotationTable, WorkerSalesResponsible));
                locQueryBuildDataSource.addRange(fieldNum(SalesQuotationTable, WorkerSalesTaker)).value(strFmt( '((%1.%2 == %4) || (%1.%3 == %4))',
                                                                                                                locQueryBuildDataSource.name(),
                                                                                                                fieldStr(SalesQuotationTable, WorkerSalesResponsible),
                                                                                                                fieldStr(SalesQuotationTable, WorkerSalesTaker),
                                                                                                                locHcmWorkerRecId
                                                                                                                ));
                break;

            case menuItemDisplayStr(AVASalesQuotationsListPageMyNotPostedDisplay):
                locHcmWorkerRecId               = HcmWorkerLookup::currentWorker();

                locFormDataSource               = this.SalesQuotationTable_DS;

                locQuery                        = locFormDataSource.query();
                locQueryBuildDataSource         = locFormDataSource.queryBuildDataSource();

                locQueryBuildRangeResponsible   = SysQuery::findOrCreateRange(locQuery.datasourceTable(tableNum(SalesQuotationTable)), fieldNum(SalesQuotationTable, WorkerSalesResponsible));
                locQueryBuildDataSource.clearRange(fieldNum(SalesQuotationTable, WorkerSalesResponsible));
                locQueryBuildDataSource.addRange(fieldNum(SalesQuotationTable, WorkerSalesTaker)).value(strFmt( '((%1.%2 == %4) || (%1.%3 == %4))',
                                                                                                                locQueryBuildDataSource.name(),
                                                                                                                fieldStr(SalesQuotationTable, WorkerSalesResponsible),
                                                                                                                fieldStr(SalesQuotationTable, WorkerSalesTaker),
                                                                                                                locHcmWorkerRecId
                                                                                                                ));
                locQueryBuildRangePosted        = SysQuery::findOrCreateRange(locQuery.datasourceTable(tableNum(SalesQuotationTable)), fieldNum(SalesQuotationTable, AVAPosted));
                locQueryBuildDataSource.clearRange(fieldNum(SalesQuotationTable, AVAPosted));
                locQueryBuildDataSource.addRange(fieldNum(SalesQuotationTable, AVAPosted)).value(queryValue(NoYes::No));
                break;

            case menuItemDisplayStr(AVASalesQuotationsListPageMyNotPostedTileDisplay):
                locHcmWorkerRecId               = HcmWorkerLookup::currentWorker();

                locFormDataSource               = this.SalesQuotationTable_DS;

                locQuery                        = locFormDataSource.query();
                locQueryBuildDataSource         = locFormDataSource.queryBuildDataSource();

                locQueryBuildRangeResponsible   = SysQuery::findOrCreateRange(locQuery.datasourceTable(tableNum(SalesQuotationTable)), fieldNum(SalesQuotationTable, WorkerSalesResponsible));
                str qbrRangeValue               = locQueryBuildRangeResponsible.value();
                locHcmWorkerRecId               = str2Int64(qbrRangeValue);
                /*
                locQueryBuildDataSource.clearRange(fieldNum(SalesQuotationTable, WorkerSalesResponsible));
                locQueryBuildDataSource.addRange(fieldNum(SalesQuotationTable, WorkerSalesTaker)).value(strFmt( '((%1.%2 == %4) || (%1.%3 == %4))',
                                                                                                                locQueryBuildDataSource.name(),
                                                                                                                fieldStr(SalesQuotationTable, WorkerSalesResponsible),
                                                                                                                fieldStr(SalesQuotationTable, WorkerSalesTaker),
                                                                                                                locHcmWorkerRecId
                                                                                                                ));
                locQueryBuildRangePosted        = SysQuery::findOrCreateRange(locQuery.datasourceTable(tableNum(SalesQuotationTable)), fieldNum(SalesQuotationTable, AVAPosted));
                locQueryBuildDataSource.clearRange(fieldNum(SalesQuotationTable, AVAPosted));
                locQueryBuildDataSource.addRange(fieldNum(SalesQuotationTable, AVAPosted)).value(queryValue(NoYes::No));
                */
                break;
        }
    }

    this.design().controlName(formControlStr(SalesQuotationListPage, CreateActivity)).visible(false);
}
